CSS:
#tabs [data-tab=fat],#tabs [data-tab=port],#tabs [data-tab=stip]{display:none!important}
#tabs{grid-template-columns:repeat(3,1fr)!important}
.jrbar{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 12px;border:1px solid var(--line);border-radius:14px;background:var(--surface);font-size:.82rem;color:var(--muted)}
.jrbar b{color:var(--fg)}
[data-cs="sca"]{display:none!important}
.segs.vtog.c3{grid-template-columns:1fr 1fr!important}
#splash b{font-size:1.05rem;letter-spacing:.3em}
.vtog[aria-label="Sezione"],.ob-mini{display:none!important}
#calF [data-f=recl],#calF [data-f=aff],#calF [data-f=pers],#calF [data-f=scad]{display:none!important}
.jrbar{flex-wrap:wrap}
.jrbar select{font-size:16px;max-width:48%;padding:4px 6px;border-radius:10px;border:1px solid var(--line);background:var(--bg);color:var(--fg)}
.jrwho{display:inline-block;margin-left:6px;padding:1px 8px;border-radius:99px;background:var(--c);color:#fff;font-size:.7rem;font-weight:700;vertical-align:middle}
.cg{gap:3px!important}
.cg .dy{aspect-ratio:auto!important;min-height:86px;align-items:stretch!important;justify-content:flex-start!important;padding:4px 2px 3px!important;gap:2px!important;border-radius:10px!important;overflow:hidden;font-size:.7rem!important}
.cg .jrdn{display:block;text-align:center;font:800 .74rem/1 var(--font-display);padding:1px 0 3px}
.cg .jrbr{display:block;background:var(--c);color:#fff;font:700 .6rem/1.25 var(--font-body);padding:1px 3px;border-radius:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:left}
.cg .jrmore{display:block;text-align:center;font:700 .6rem var(--font-body);color:var(--muted)}
.cg .dy.sel .jrmore{color:#fff}
.cgl button{display:inline-flex;align-items:center;gap:5px;border:1px solid var(--line);background:var(--surface);color:var(--fg);border-radius:99px;padding:3px 10px;font:700 .74rem var(--font-body)}
.cgl button[aria-pressed=true]{background:var(--accent);color:#fff;border-color:transparent}
.cgl button i{width:9px;height:9px;border-radius:50%;display:block}
#calF,#calP,.chips:has([data-pp]){display:none!important}
.cg .jrbr{background:rgba(128,128,128,.16);background:color-mix(in srgb,var(--c) 17%,transparent);color:var(--c);box-shadow:inset 2px 0 0 var(--c)}
.jrmeta{font-size:.74rem;color:var(--muted);margin-top:2px}.jrmeta b{color:var(--fg)}
.jrswg{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-top:6px}
.jrsq{aspect-ratio:1;border-radius:50%;border:3px solid transparent;background:var(--c);padding:0;min-width:0}
.jrsq[aria-pressed=true]{border-color:var(--fg);box-shadow:0 0 0 2px var(--surface) inset}
.jrsq:disabled{opacity:.18}
.jrsec{font:800 .8rem var(--font-display);letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin:6px 2px 0}
body[data-view="sum"] #add{display:none!important}
.jrbox{display:grid;gap:10px}
.jrws{display:block;width:100%;border:1px solid var(--line);background:var(--surface);border-radius:14px;padding:6px 8px;opacity:.5;transform:scale(.95);color:var(--fg);text-align:left}
.jrwl{display:block;font:700 .66rem var(--font-body);color:var(--muted);margin-bottom:3px}
.jrwc{display:grid;grid-template-columns:repeat(7,1fr);gap:2px}
.jrwc>span{display:flex;flex-direction:column;align-items:center;gap:2px}
.jrwc em{font:800 .72rem var(--font-display);font-style:normal}
.jrwc i{display:flex;gap:2px;min-height:5px}
.jrwc u{width:5px;height:5px;border-radius:50%;display:block}
.jrwm{border:1px solid var(--line);background:var(--surface);border-radius:20px;padding:10px 10px 6px;box-shadow:0 10px 30px -12px rgba(0,0,0,.25)}
.jrwh{display:flex;align-items:center;gap:8px;margin-bottom:6px}
.jrwh b{font:800 1.05rem var(--font-display)}
.jrwh span{flex:1;color:var(--muted);font-size:.8rem}
.jrdr{display:flex;gap:10px;padding:9px 4px;border-top:1px solid var(--line);min-height:54px}
.jrdr.today .jrdd b{background:var(--accent);color:#fff}
.jrdd{width:44px;text-align:center;flex:none}
.jrdd small{display:block;font:700 .66rem var(--font-body);color:var(--muted);text-transform:uppercase}
.jrdd b{display:inline-block;min-width:30px;line-height:30px;border-radius:50%;font:800 1.05rem var(--font-display)}
.jrde{flex:1;display:grid;gap:5px;align-content:center;min-width:0}
.jrev{display:block;width:100%;text-align:left;border:0;border-radius:10px;padding:6px 9px;background:rgba(128,128,128,.14);background:color-mix(in srgb,var(--c) 16%,transparent);box-shadow:inset 3px 0 0 var(--c);color:var(--c)}
.jrev .jrn{font:800 .95rem/1.2 var(--font-display)}
.jrev .jrt{font:700 .75rem var(--font-body);margin-right:6px;opacity:.85}
.jrev small{display:block;color:var(--muted);font-size:.72rem;margin-top:1px}
.jrfree{color:var(--muted);opacity:.5;font-size:.8rem}
.jrcf{position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.45);display:flex;align-items:center;justify-content:center;padding:20px}
.jrcfb{width:100%;max-width:360px;background:var(--surface);color:var(--fg);border-radius:22px;padding:20px 18px 16px;box-shadow:0 20px 50px -10px rgba(0,0,0,.45);text-align:center;animation:jrpop .22s ease-out}
.jrcfe{font-size:2.2rem;line-height:1}
.jrcfb h3{font:800 1.2rem var(--font-display);margin:6px 0 4px}
.jrcfb p{margin:0;color:var(--muted);font-size:.9rem}
.jrcfb ul{list-style:none;padding:0;margin:10px 0 14px;display:grid;gap:6px;text-align:left}
.jrcfb li{background:rgba(128,128,128,.14);border-radius:12px;padding:8px 10px;font-size:.88rem;line-height:1.3}
.jrcfa{display:grid;grid-template-columns:1fr 1fr;gap:8px}
@keyframes jrpop{from{transform:scale(.9);opacity:0}to{transform:none;opacity:1}}
.jrwm{padding:8px 4px 6px}
.jrwh{padding:0 6px}
.jrwg{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px}
.jrcol{min-width:0;border-radius:10px;padding:2px 1px 6px;min-height:300px;display:flex;flex-direction:column;gap:3px}
.jrcol.today{background:rgba(128,128,128,.12);background:color-mix(in srgb,var(--accent) 10%,transparent)}
.jrcol.past .jrcb{opacity:.6}
.jrch{text-align:center;padding:2px 0 3px}
.jrch small{display:block;font:700 .62rem var(--font-body);color:var(--muted);letter-spacing:.04em}
.jrch small.sun{color:var(--accent)}
.jrch b{display:inline-block;min-width:26px;line-height:26px;border-radius:50%;font:800 .95rem var(--font-display)}
.jrcol.today .jrch b{background:var(--accent);color:#fff}
.jrcb{display:flex;flex-direction:column;gap:3px;min-width:0}
.jrk{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;width:100%;border:0;text-align:left;border-radius:6px;padding:3px 4px;font:700 .64rem/1.15 var(--font-body);background:rgba(128,128,128,.16);background:color-mix(in srgb,var(--c) 18%,transparent);color:var(--c);box-shadow:inset 2px 0 0 var(--c);word-break:break-word;min-width:0}
.jrwc i{flex-direction:column;align-items:stretch;width:100%;gap:2px;min-height:6px}
.jrwc u{width:100%;height:5px;border-radius:3px}

